function PVPArenaRankFlagNode:RefreshUI(rank)
    local rankTile = PVPArenaUtils.GetRankTitleByRank(rank)
    local isOwnRankTitle = rankTile ~= nil
    KTool.SetActive(self.Roundbg.gameObject, not isOwnRankTitle)
    KTool.SetActive(self.Flagbg.gameObject, isOwnRankTitle)

    local rankImgTable = PVPArenaUtils.GetRankImgNameByRank(rank)
    local rankNumImgName, rankLightImgName = SafeUnpack(rankImgTable or {})
    if isOwnRankTitle then
        self.Text.text = rankTile
        self.ImgOne:LoadSprite(string.format(BasePath, rankNumImgName))
        self.Imglight:LoadSprite(string.format(BasePath, rankLightImgName))
    else
        if rankNumImgName then
            self.Imgnumber:LoadSprite(string.format(BasePath, rankNumImgName))
        end
    end
end

